package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.ScreenFamily;
import net.minecraft.world.phys.AABB;
/** Compare emitted native block boxes to independently frozen actual Source block queries. */
public final class ScreenGeometryChecks {
 public static void main(String[] args)throws Exception {JsonObject reference;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenGeometryReference")))){reference=JsonParser.parseReader(reader).getAsJsonObject();}boolean chip=reference.getAsJsonArray("cases").get(0).getAsJsonObject().has("chip");int cases=0,boxes=0;for(var entry:reference.getAsJsonArray("cases")){var expected=entry.getAsJsonObject();ScreenFamily family=ScreenFamily.fromId(expected.get("id").getAsString());int ceiling=expected.get("ceiling").getAsInt();var actual=NativeScreenGeometry.of(family,family.decode(expected.get("meta").getAsInt()),expected.get("small").getAsBoolean(),expected.get("wall").getAsInt(),ceiling>=0,ceiling,chip);compare(actual.bounds(),expected.getAsJsonArray("bounds"));var collision=expected.getAsJsonArray("collision");if(actual.collision().size()!=collision.size())throw new AssertionError("Collision count "+expected);for(int i=0;i<collision.size();i++){compare(actual.collision().get(i),collision.get(i).getAsJsonArray());boxes++;}try{actual.collision().clear();throw new AssertionError("Mutable geometry");}catch(UnsupportedOperationException expectedImmutable){}rays(family,family.decode(expected.get("meta").getAsInt()),actual,expected.getAsJsonArray("rays"));cases++;}if(cases!=(chip?1024:2240)||boxes!=(chip?8320:8768)||!reference.get("sha256").getAsString().equals(chip?"4ac07567059881a48e2b6ffde02a49b1ac014e59c403ff9c877a88c2bb7210ec":"83ede38318365cfad58149c9bb770d2ee211aa96d80dccc0f0aeec0768c779af"))throw new AssertionError("Source coverage changed");System.out.println("Native Screen block geometry PASS cases="+cases+" collisionBoxes="+boxes+" exact Source bounds and "+(cases*27)+" ray hits/faces; selectedChip="+chip);}
 private static void rays(ScreenFamily family,ScreenFamily.State state,NativeScreenGeometry geometry,JsonArray expected){int index=0;for(int axis=0;axis<3;axis++)for(int a=0;a<3;a++)for(int b=0;b<3;b++){double[] start={a/2D,b/2D,.5},end=start.clone();int other=(axis+1)%3,last=(axis+2)%3;start[axis]=-2;end[axis]=3;start[other]=end[other]=a/2D;start[last]=end[last]=b/2D;var hit=NativeScreenPicking.trace(family,state,geometry,new net.minecraft.world.phys.Vec3(start[0],start[1],start[2]),new net.minecraft.world.phys.Vec3(end[0],end[1],end[2]));var source=expected.get(index++);if(source.isJsonNull()){if(hit!=null)throw new AssertionError("Unexpected native hit "+family+" ray="+(index-1));}else {var point=source.getAsJsonArray();if(hit==null||Math.abs(hit.x-point.get(0).getAsDouble())>1e-12||Math.abs(hit.y-point.get(1).getAsDouble())>1e-12||Math.abs(hit.z-point.get(2).getAsDouble())>1e-12||hit.face!=point.get(3).getAsInt())throw new AssertionError("Native ray differs "+family+" ray="+(index-1)+" face="+(hit==null?"null":hit.face)+" source="+source);}}}
 private static void compare(AABB actual,JsonArray expected){double[] values={actual.minX,actual.minY,actual.minZ,actual.maxX,actual.maxY,actual.maxZ};for(int i=0;i<6;i++)if(Math.abs(values[i]-expected.get(i).getAsDouble())>1e-12)throw new AssertionError("Box differs "+actual+" expected "+expected);}
}
